package com.optilive.tracker
import android.content.Intent
import android.os.Bundle
import android.webkit.*
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
class MapActivity:AppCompatActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContentView(R.layout.activity_map);val p=getSharedPreferences("optilive_profile",MODE_PRIVATE);var u=(p.getString("server_url","")?:"").trim();if(u.isNotBlank()&&!u.startsWith("http"))u="http://$u";findViewById<TextView>(R.id.raceName).text="Trofeo Fornells 2026";findViewById<TextView>(R.id.raceClub).text=p.getString("club","C.M. Mahón")?:"C.M. Mahón";findViewById<TextView>(R.id.liveStatus).text=if(u.isBlank())"● Sin conexión" else "● En directo";val w=findViewById<WebView>(R.id.webMap);w.settings.javaScriptEnabled=true;w.settings.domStorageEnabled=true;w.settings.mixedContentMode=WebSettings.MIXED_CONTENT_ALWAYS_ALLOW;w.loadUrl(if(u.isBlank())"https://optilive-node-production.up.railway.app" else u);findViewById<TextView>(R.id.backTracking).setOnClickListener{finish()};findViewById<TextView>(R.id.zoomIn).setOnClickListener{w.evaluateJavascript("if(window.map)map.zoomIn()",null)};findViewById<TextView>(R.id.zoomOut).setOnClickListener{w.evaluateJavascript("if(window.map)map.zoomOut()",null)};findViewById<TextView>(R.id.centerMap).setOnClickListener{w.evaluateJavascript("if(window.focusLive)window.focusLive()",null)};findViewById<TextView>(R.id.classificationNav).setOnClickListener{startActivity(Intent(this,ClassificationActivity::class.java));finish()};findViewById<TextView>(R.id.trackingNav).setOnClickListener{startActivity(Intent(this,TrackingActivity::class.java));finish()};findViewById<TextView>(R.id.optionsNav).setOnClickListener{startActivity(Intent(this,MainActivity::class.java));finish()}}}